export default JSON.parse("{\"workId\":\"xunzi\",\"chapter\":{\"id\":\"xunzi_ch-10\",\"workId\":\"xunzi\",\"order\":10,\"title\":\"富國\",\"difficulty\":4,\"estimatedMinutes\":17,\"passageIds\":[\"xunzi_ch-10_p-1\",\"xunzi_ch-10_p-2\",\"xunzi_ch-10_p-3\",\"xunzi_ch-10_p-4\",\"xunzi_ch-10_p-5\",\"xunzi_ch-10_p-6\",\"xunzi_ch-10_p-7\",\"xunzi_ch-10_p-8\",\"xunzi_ch-10_p-9\",\"xunzi_ch-10_p-10\",\"xunzi_ch-10_p-11\",\"xunzi_ch-10_p-12\",\"xunzi_ch-10_p-13\",\"xunzi_ch-10_p-14\",\"xunzi_ch-10_p-15\",\"xunzi_ch-10_p-16\",\"xunzi_ch-10_p-17\",\"xunzi_ch-10_p-18\",\"xunzi_ch-10_p-19\"],\"tags\":[\"儒家\",\"性惡論\",\"禮樂\"]},\"passages\":[{\"id\":\"xunzi_ch-10_p-1\",\"chapterId\":\"xunzi_ch-10\",\"order\":1,\"canonicalText\":\"萬物同宇而異體，無宜而有用為人，數也。人倫並處，同求而異道，同欲而異知，生也。皆有可也，知愚同；所可異也，知愚分。埶同而知異，行私而無禍，縱欲而不窮，則民心奮而不可說也。如是，則知者未得治也；知者未得治，則功名未成也；功名未成，則羣眾未縣也；羣眾未縣，則君臣未立也。無君以制臣，無上以制下，天下害生縱欲。欲惡同物，欲多而物寡，寡則必爭矣。故百技所成，所以養一人也。而能不能兼技，人不能兼官。離居不相待則窮，羣居而無分則爭；窮者患也，爭者禍也，救患除禍，則莫若明分使羣矣。彊脅弱也，知懼愚也，民下違上，少陵長，不以德為政：如是，則老弱有失養之憂，而壯者有分爭之禍矣。事業所惡也，功利所好也，職業無分：如是，則人有樹事之患，而有爭功之禍矣。男女之合，夫婦之分，婚姻娉內，送逆無禮：如是，則人有失合之憂，而有爭色之禍矣。故知者為之分也。\",\"sentenceIds\":[\"xunzi_ch-10_p-1_s-1\",\"xunzi_ch-10_p-1_s-2\",\"xunzi_ch-10_p-1_s-3\",\"xunzi_ch-10_p-1_s-4\",\"xunzi_ch-10_p-1_s-5\",\"xunzi_ch-10_p-1_s-6\",\"xunzi_ch-10_p-1_s-7\",\"xunzi_ch-10_p-1_s-8\",\"xunzi_ch-10_p-1_s-9\",\"xunzi_ch-10_p-1_s-10\",\"xunzi_ch-10_p-1_s-11\",\"xunzi_ch-10_p-1_s-12\",\"xunzi_ch-10_p-1_s-13\",\"xunzi_ch-10_p-1_s-14\",\"xunzi_ch-10_p-1_s-15\",\"xunzi_ch-10_p-1_s-16\",\"xunzi_ch-10_p-1_s-17\",\"xunzi_ch-10_p-1_s-18\",\"xunzi_ch-10_p-1_s-19\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"萬物同宇而且異體，無宜而且有用為人，數啊。人倫並處，同求而且異道，同欲而且異知，生啊。皆有可啊，知愚同；所可異啊，知愚分。埶同而且知異，行私而且無禍，縱欲而且不窮，則民心奮而且不可說啊。如是，則知的人或事物未得治啊；知的人或事物未得治，則功名未成啊；功名未成，則羣眾未縣啊；羣眾未縣，則君臣未立啊。無君以制臣，無上以制下，天下害生縱欲。欲惡同物，欲多而且物寡，寡則必爭矣。所以百技所成，所以養一人啊。而且能不能兼技，人不能兼官。離居不相待則窮，羣居而且無分則爭；窮的人或事物患啊，爭的人或事物禍啊，救患除禍，則莫若明分使羣矣。彊脅弱啊，知懼愚啊，民下違上，少陵長，不以品德修養為政：如是，則老弱有失養的憂，而且壯的人或事物有分爭的禍矣。事業所惡啊，功利所好啊，職業無分：如是，則人有樹事的患，而且有爭功的禍矣。男女的合，夫婦的分，婚姻娉內，送逆無禮正義道義道品德修養規程：如是，則人有失合的憂，而且有爭色的禍矣。所以知的人或事物為的分啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 1 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「萬物同宇而異體，無宜而有用為人，數也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「萬物同宇而異體，無宜而有用為人，數也。人倫並處，同求……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-2\",\"chapterId\":\"xunzi_ch-10\",\"order\":2,\"canonicalText\":\"足國之道：節用裕民，而善臧其餘。節用以禮，裕民以政。彼裕民，故多餘。裕民則民富，民富則田肥以易，田肥以易則出實百倍。上以法取焉，而下以禮節用之，餘若丘山，不時焚燒，無所臧之。夫君子奚患乎無餘？故知節用裕民，則必有仁聖賢良之名，而且有富厚丘山之積矣。此無他故焉，生於節用裕民也。不知節用裕民則民貧，民貧則田瘠以穢，田瘠以穢則出實不半；上雖好取侵奪，猶將寡獲也。而或以無禮節用之，則必有貪利糾譑之名，而且有空虛窮乏之實矣。此無他故焉，不知節用裕民也。《康誥》曰：「弘覆乎天，若德裕乃身。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-2_s-1\",\"xunzi_ch-10_p-2_s-2\",\"xunzi_ch-10_p-2_s-3\",\"xunzi_ch-10_p-2_s-4\",\"xunzi_ch-10_p-2_s-5\",\"xunzi_ch-10_p-2_s-6\",\"xunzi_ch-10_p-2_s-7\",\"xunzi_ch-10_p-2_s-8\",\"xunzi_ch-10_p-2_s-9\",\"xunzi_ch-10_p-2_s-10\",\"xunzi_ch-10_p-2_s-11\",\"xunzi_ch-10_p-2_s-12\",\"xunzi_ch-10_p-2_s-13\",\"xunzi_ch-10_p-2_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"足國的道：節用裕民，而且善臧他的餘。節用以禮正義道義道品德修養規程，裕民以政。彼裕民，所以多餘。裕民則民富，民富則田肥以易，田肥以易則出實百倍。上以國家典章法度取焉，而且下以禮正義道義道品德修養規程節用的，餘若丘山，不時焚燒，無所臧的。夫君子奚患乎無餘？所以知節用裕民，則必有仁愛慈悲之德聖賢良的名，而且且有富厚丘山的積矣。此無他所以焉，生於節用裕民啊。不知節用裕民則民貧，民貧則田瘠以穢，田瘠以穢則出實不半；上雖好取侵奪，猶將寡獲啊。而且或以無禮正義道義道品德修養規程節用的，則必有貪利糾譑的名，而且且有空虛窮乏的實矣。此無他所以焉，不知節用裕民啊。《康誥》說道：弘覆乎天，若品德修養裕乃身。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 2 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「足國之道：節用裕民，而善臧其餘」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「足國之道：節用裕民，而善臧其餘。節用以禮，裕民以政。……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-3\",\"chapterId\":\"xunzi_ch-10\",\"order\":3,\"canonicalText\":\"禮者，貴賤有等；長幼有差，貧富輕重皆有稱者也。故天子袾裷衣冕，諸侯玄裷衣冕，大夫裨冕，士皮弁服。德必稱位，位必稱祿，祿必稱用，由士以上則必以禮樂節之，眾庶百姓則必以法數制之。量地而立國，計利而畜民，度人力而授事，使民必勝事，事必出利，利足以生民，皆使衣食百用出入相揜，必時臧餘，謂之稱數。故自天子通於庶人，事無大小多少，由是推之。故曰：「朝無幸位，民無幸生。」此之謂也。輕田野之賦，平關市之徵，省商賈之數，罕興力役，無奪農時，如是則國富矣。夫是之謂以政裕民。\",\"sentenceIds\":[\"xunzi_ch-10_p-3_s-1\",\"xunzi_ch-10_p-3_s-2\",\"xunzi_ch-10_p-3_s-3\",\"xunzi_ch-10_p-3_s-4\",\"xunzi_ch-10_p-3_s-5\",\"xunzi_ch-10_p-3_s-6\",\"xunzi_ch-10_p-3_s-7\",\"xunzi_ch-10_p-3_s-8\",\"xunzi_ch-10_p-3_s-9\",\"xunzi_ch-10_p-3_s-10\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"禮正義道義道品德修養規程的人或事物，貴賤有等；長幼有差，貧富輕重皆有稱的人或事物啊。所以天子袾裷衣冕，諸侯玄裷衣冕，大夫裨冕，士皮弁服。品德修養必稱位，位必稱祿，祿必稱用，由士以上則必以禮正義道義道品德修養規程樂節的，眾庶百姓則必以國家典章法度數制的。量地而且立國，計利而且畜民，度人力而且授事，使民必勝事，事必出利，利足以生民，皆使衣食百用出入相揜，必時臧餘，謂的稱數。所以自天子通於庶人，事無大小多少，由是推的。所以古聖先賢說道：朝無幸位，民無幸生。此的謂啊。輕田野的賦，平關市的徵，省商賈的數，罕興力役，無奪農時，如是則國富矣。這就是儒家所稱的以政裕民。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 3 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「禮者，貴賤有等」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「禮者，貴賤有等；長幼有差，貧富輕重皆有稱者也。故天子……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-4\",\"chapterId\":\"xunzi_ch-10\",\"order\":4,\"canonicalText\":\"人之生不能無羣，羣而無分則爭，爭則亂，亂則窮矣。故無分者，人之大害也；有分者，天下之本利也；而人君者，所以管分之樞要也。故美之者，是美天下之本也；安之者，是安天下之本也；貴之者，是貴天下之本也。古者先王分割而等異之也，故使或美，或惡，或厚，或薄，或佚或樂，或劬或勞，非特以為淫泰誇麗之聲，將以明仁之文，通仁之順也。故為之雕琢、刻鏤、黼黻文章，使足以辨貴賤而已，不求其觀；為之鐘鼓、管磬、琴瑟、竽笙，使足以辨吉凶、合歡、定和而已，不求其餘；為之宮室、臺榭，使足以避燥溼、養德、辨輕重而已，不求其外。《詩》曰：「雕琢其章，金玉其相，亹亹我王，綱紀四方。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-4_s-1\",\"xunzi_ch-10_p-4_s-2\",\"xunzi_ch-10_p-4_s-3\",\"xunzi_ch-10_p-4_s-4\",\"xunzi_ch-10_p-4_s-5\",\"xunzi_ch-10_p-4_s-6\",\"xunzi_ch-10_p-4_s-7\",\"xunzi_ch-10_p-4_s-8\",\"xunzi_ch-10_p-4_s-9\",\"xunzi_ch-10_p-4_s-10\",\"xunzi_ch-10_p-4_s-11\",\"xunzi_ch-10_p-4_s-12\",\"xunzi_ch-10_p-4_s-13\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"人的生不能無羣，羣而且無分則爭，爭則亂，亂則窮矣。所以無分的人或事物，人的大害啊；有分的人或事物，天下的本利啊；而且人君的人或事物，所以管分的樞要啊。所以美的的人或事物，是美天下的本啊；安的的人或事物，是安天下的本啊；貴的的人或事物，是貴天下的本啊。古的人或事物先王分割而且等異的啊，所以使或美，或惡，或厚，或薄，或佚或樂，或劬或勞，絕不是特以為淫泰誇麗的聲，將以明仁愛慈悲之德的文，通仁愛慈悲之德的順啊。所以為的雕琢、刻鏤、黼黻文章，使足以辨貴賤而且已，不求他的觀；為的鐘鼓、管磬、琴瑟、竽笙，使足以辨吉凶、合歡、定和而且已，不求他的餘；為的宮室、臺榭，使足以避燥溼、養品德修養、辨輕重而且已，不求他的外。《詩》說道：雕琢他的章，金玉他的相，亹亹我王，綱紀四方。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 4 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「人之生不能無羣，羣而無分則爭，爭則亂，亂則窮矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「人之生不能無羣，羣而無分則爭，爭則亂，亂則窮矣。故無……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-5\",\"chapterId\":\"xunzi_ch-10\",\"order\":5,\"canonicalText\":\"若夫重色而衣之，重味而食之，重財物而制之，合天下而君之，非特以為淫泰也，固以為主天下，治萬變，材萬物，養萬民，兼制天下者，為莫若仁人之善也夫。故其知慮足以治之，其仁厚足以安之，其德音足以化之，得之則治，失之則亂。百姓誠賴其知也，故相率而為之勞苦以務佚之，以養其知也；誠美其厚也，故為之出死斷亡以覆救之，以養其厚也；誠美其德也，故為之雕琢、刻鏤、黼黻、文章以藩飾之，以養其德也。故仁人在上，百姓貴之如帝，親之如父母，為之出死斷亡而愉者，無它故焉，其所是焉誠美，其所得焉誠大，其所利焉誠多。《詩》曰：「我任我輦，我車我牛，我行既集，蓋雲歸哉！」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-5_s-1\",\"xunzi_ch-10_p-5_s-2\",\"xunzi_ch-10_p-5_s-3\",\"xunzi_ch-10_p-5_s-4\",\"xunzi_ch-10_p-5_s-5\",\"xunzi_ch-10_p-5_s-6\",\"xunzi_ch-10_p-5_s-7\",\"xunzi_ch-10_p-5_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"至於談到那重色而且衣的，重味而且食的，重財物而且制的，合天下而且君的，絕不是特以為淫泰啊，固以為主天下，治萬變，材萬物，養萬民，兼制天下的人或事物，為莫若仁愛慈悲之德人的善啊夫。所以他的知慮足以治的，他的仁愛慈悲之德厚足以安的，他的品德修養音足以化的，得的則治，失的則亂。百姓誠賴他的知啊，所以相率而且為的勞苦以務佚的，以養他的知啊；誠美他的厚啊，所以為的出死斷亡以覆救的，以養他的厚啊；誠美他的品德修養啊，所以為的雕琢、刻鏤、黼黻、文章以藩飾的，以養他的品德修養啊。所以仁愛慈悲之德人在上，百姓貴的如帝，親的如父母，為的出死斷亡而且愉的人或事物，無它所以焉，他的所是焉誠美，他的所得焉誠大，他的所利焉誠多。《詩》說道：我任我輦，我車我牛，我行既集，蓋雲歸哉！此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 5 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「若夫重色而衣之，重味而食之，重財物而制之，合天下而君之，非特以為淫泰也，固以為主天下，治萬變，材萬物，養萬民，兼制天下者，為莫若仁人之善也夫」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「若夫重色而衣之，重味而食之，重財物而制之，合天下而君……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-6\",\"chapterId\":\"xunzi_ch-10\",\"order\":6,\"canonicalText\":\"故曰：君子以德，小人以力；力者，德之役也。百姓之力，待之而後功；百姓之羣，待之而後和；百姓之財，待之而後聚；百姓之埶，待之而後安；百姓之壽，待之而後長；父子不得不親，兄弟不得不順，男女不得不歡。少者以長，老者以養。故曰：「天地生之，聖人成之。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-6_s-1\",\"xunzi_ch-10_p-6_s-2\",\"xunzi_ch-10_p-6_s-3\",\"xunzi_ch-10_p-6_s-4\",\"xunzi_ch-10_p-6_s-5\",\"xunzi_ch-10_p-6_s-6\",\"xunzi_ch-10_p-6_s-7\",\"xunzi_ch-10_p-6_s-8\",\"xunzi_ch-10_p-6_s-9\",\"xunzi_ch-10_p-6_s-10\",\"xunzi_ch-10_p-6_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以古聖先賢說道：君子以品德修養，小人以力；力的人或事物，品德修養的役啊。百姓的力，待的而且後功；百姓的羣，待的而且後和；百姓的財，待的而且後聚；百姓的埶，待的而且後安；百姓的壽，待的而且後長；父子不得不親，兄弟不得不順，男女不得不歡。少的人或事物以長，老的人或事物以養。所以古聖先賢說道：天地生的，聖人成的。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 6 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故曰：君子以德，小人以力」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故曰：君子以德，小人以力；力者，德之役也。百姓之力，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-7\",\"chapterId\":\"xunzi_ch-10\",\"order\":7,\"canonicalText\":\"今之世而不然：厚刀布之斂，以奪之財；重田野之賦，以奪之食；苛關市之徵，以難其事。不然而已矣：有掎絜伺詐，權謀傾覆，以相顛倒，以靡敝之。百姓曉然皆知其汙漫暴亂，而將大危亡也。是以臣或弒其君，下或殺其上，粥其城，倍其節，而不死其事者，無他故焉，人主自取之。《詩》曰：「無言不讎，無德不報。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-7_s-1\",\"xunzi_ch-10_p-7_s-2\",\"xunzi_ch-10_p-7_s-3\",\"xunzi_ch-10_p-7_s-4\",\"xunzi_ch-10_p-7_s-5\",\"xunzi_ch-10_p-7_s-6\",\"xunzi_ch-10_p-7_s-7\",\"xunzi_ch-10_p-7_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"今的世而且不然：厚刀布的斂，以奪的財；重田野的賦，以奪的食；苛關市的徵，以難他的事。不然而且已矣：有掎絜伺詐，權謀傾覆，以相顛倒，以靡敝的。百姓曉然皆知他的汙漫暴亂，而且將大危亡啊。是以臣或弒他的君，下或殺他的上，粥他的城，倍他的節，而且不死他的事的人或事物，無他所以焉，人主自取的。《詩》說道：無言不讎，無品德修養不報。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 7 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「今之世而不然：厚刀布之斂，以奪之財」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「今之世而不然：厚刀布之斂，以奪之財；重田野之賦，以奪……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-8\",\"chapterId\":\"xunzi_ch-10\",\"order\":8,\"canonicalText\":\"兼足天下之道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶之事也。守時力民，進事長功，和齊百姓，使人不偷，是將率之事也。高者不旱，下者不水，寒暑和節，而五穀以時孰，是天之事也。若夫兼而覆之，兼而愛之，兼而制之，歲雖兇敗水旱，使百姓無凍餧之患，則是聖君賢相之事也。\",\"sentenceIds\":[\"xunzi_ch-10_p-8_s-1\",\"xunzi_ch-10_p-8_s-2\",\"xunzi_ch-10_p-8_s-3\",\"xunzi_ch-10_p-8_s-4\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"兼足天下的道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶的事啊。守時力民，進事長功，和齊百姓，使人不偷，是將率的事啊。高的人或事物不旱，下的人或事物不水，寒暑和節，而且五穀以時孰，是天的事啊。至於談到那兼而且覆的，兼而且愛的，兼而且制的，歲雖兇敗水旱，使百姓無凍餧的患，則是聖君賢相的事啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 8 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「兼足天下之道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶之事也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「兼足天下之道在明分：掩地表畝，刺屮殖穀，多糞肥田，是……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-9\",\"chapterId\":\"xunzi_ch-10\",\"order\":9,\"canonicalText\":\"墨子之言昭昭然為天下憂不足。夫不足非天下之公患也，特墨子之私憂過計也。今是土之生五穀也，人善治之，則畝數盆，一歲而再獲之。然後瓜桃棗李一本數以盆鼓；然後葷菜百疏以澤量；然後六畜禽獸一而剸車；黿、鼉、魚、鱉、鰍、鱣以時別，一而成羣；然後飛鳥、鳧、雁若煙海；然後昆蟲萬物生其間，可以相食養者，不可勝數也。夫天地之生萬物也，固有餘，足以食人矣；麻葛繭絲、鳥獸之羽毛齒革也，固有餘，足以衣人矣。夫有餘不足，非天下之公患也，特墨子之私憂過計也。\",\"sentenceIds\":[\"xunzi_ch-10_p-9_s-1\",\"xunzi_ch-10_p-9_s-2\",\"xunzi_ch-10_p-9_s-3\",\"xunzi_ch-10_p-9_s-4\",\"xunzi_ch-10_p-9_s-5\",\"xunzi_ch-10_p-9_s-6\",\"xunzi_ch-10_p-9_s-7\",\"xunzi_ch-10_p-9_s-8\",\"xunzi_ch-10_p-9_s-9\",\"xunzi_ch-10_p-9_s-10\",\"xunzi_ch-10_p-9_s-11\",\"xunzi_ch-10_p-9_s-12\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"墨子的言昭昭然為天下憂不足。夫不足絕不是天下的公患啊，特墨子的私憂過計啊。今是土的生五穀啊，人善治的，則畝數盆，一歲而且再獲的。然後瓜桃棗李一本數以盆鼓；然後葷菜百疏以澤量；然後六畜禽獸一而且剸車；黿、鼉、魚、鱉、鰍、鱣以時別，一而且成羣；然後飛鳥、鳧、雁若煙海；然後昆蟲萬物生他的間，可以相食養的人或事物，不可勝數啊。夫天地的生萬物啊，固有餘，足以食人矣；麻葛繭絲、鳥獸的羽毛齒革啊，固有餘，足以衣人矣。夫有餘不足，絕不是天下的公患啊，特墨子的私憂過計啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 9 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「墨子之言昭昭然為天下憂不足」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「墨子之言昭昭然為天下憂不足。夫不足非天下之公患也，特……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-10\",\"chapterId\":\"xunzi_ch-10\",\"order\":10,\"canonicalText\":\"天下之公患，亂傷之也。胡不嘗試相與求亂之者誰也？我以墨子之「非樂」也，則使天下亂；墨子之「節用」也，則使天下貧，非將墮之也，說不免焉。墨子大有天下，小有一國，將蹙然衣粗食惡，憂戚而非樂。若是則瘠，瘠則不足欲；不足欲則賞不行。墨子大有天下，小有一國，將少人徒，省官職，上功勞苦，與百姓均事業，齊功勞。若是則不威；不威則罰不行。賞不行，則賢者不可得而進也；罰不行，則不肖者不可得而退也。賢者不可得而進也，不肖者不可得而退也，則能不能不可得而官也。若是，則萬物失宜，事變失應，上失天時，下失地利，中失人和，天下敖然，若燒若焦，墨子雖為之衣褐帶索，嚽菽飲水，惡能足之乎？既以伐其本，竭其原，而焦天下矣。\",\"sentenceIds\":[\"xunzi_ch-10_p-10_s-1\",\"xunzi_ch-10_p-10_s-2\",\"xunzi_ch-10_p-10_s-3\",\"xunzi_ch-10_p-10_s-4\",\"xunzi_ch-10_p-10_s-5\",\"xunzi_ch-10_p-10_s-6\",\"xunzi_ch-10_p-10_s-7\",\"xunzi_ch-10_p-10_s-8\",\"xunzi_ch-10_p-10_s-9\",\"xunzi_ch-10_p-10_s-10\",\"xunzi_ch-10_p-10_s-11\",\"xunzi_ch-10_p-10_s-12\",\"xunzi_ch-10_p-10_s-13\",\"xunzi_ch-10_p-10_s-14\",\"xunzi_ch-10_p-10_s-15\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"天下的公患，亂傷的啊。胡不嘗試相與求亂的的人或事物誰啊？我以墨子的絕不是樂啊，則使天下亂；墨子的節用啊，則使天下貧，絕不是將墮的啊，說不免焉。墨子大有天下，小有一國，將蹙然衣粗食惡，憂戚而且絕不是樂。若是則瘠，瘠則不足欲；不足欲則賞不行。墨子大有天下，小有一國，將少人徒，省官職，上功勞苦，與百姓均事業，齊功勞。若是則不威；不威則罰不行。賞不行，則賢的人或事物不可得而且進啊；罰不行，則不肖的人或事物不可得而且退啊。賢的人或事物不可得而且進啊，不肖的人或事物不可得而且退啊，則能不能不可得而且官啊。若是，則萬物失宜，事變失應，上失天時，下失地利，中失人和，天下敖然，若燒若焦，墨子雖為的衣褐帶索，嚽菽飲水，惡能足的乎？既以伐他的本，竭他的原，而且焦天下矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 10 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「天下之公患，亂傷之也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「天下之公患，亂傷之也。胡不嘗試相與求亂之者誰也？我以……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-11\",\"chapterId\":\"xunzi_ch-10\",\"order\":11,\"canonicalText\":\"故先王聖人為之不然：知夫為人主上者，不美不飾之不足以一民也，不富不厚之不足以管下也，不威不強之不足以禁暴勝悍也，故必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞其耳；必將錭琢刻鏤，黼黻文章，以塞其目；必將芻豢稻粱，五味芬芳，以塞其口。然後眾人徒，備官職，漸慶賞，嚴刑罰，以戒其心。使天下生民之屬，皆知己之所願欲之舉在是於也，故其賞行；皆知己之所畏恐之舉在是於也，故其罰威。賞行罰威，則賢者可得而進也，不肖者可得而退也，能不能可得而官也。若是則萬物得其宜，事變得應，上得天時，下得地利，中得人和，則財貨渾渾如泉源，汸汸如河海，暴暴如丘山，不時焚燒，無所臧之。夫天下何患乎不足也？故儒術誠行，則天下大而富，使而功，撞鐘擊鼓而和。《詩》曰：「鐘鼓喤喤，管磬瑲瑲，降福穰穰，降福簡簡，威儀反反。既醉既飽，福祿來反。」此之謂也。故墨術誠行，則天下尚儉而彌貧，非鬥而日爭，勞苦頓萃，而愈無功，愀然憂戚非樂，而日不和。《詩》曰：「天方薦瘥，喪亂弘多，民言無嘉，憯莫懲嗟。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-11_s-1\",\"xunzi_ch-10_p-11_s-2\",\"xunzi_ch-10_p-11_s-3\",\"xunzi_ch-10_p-11_s-4\",\"xunzi_ch-10_p-11_s-5\",\"xunzi_ch-10_p-11_s-6\",\"xunzi_ch-10_p-11_s-7\",\"xunzi_ch-10_p-11_s-8\",\"xunzi_ch-10_p-11_s-9\",\"xunzi_ch-10_p-11_s-10\",\"xunzi_ch-10_p-11_s-11\",\"xunzi_ch-10_p-11_s-12\",\"xunzi_ch-10_p-11_s-13\",\"xunzi_ch-10_p-11_s-14\",\"xunzi_ch-10_p-11_s-15\",\"xunzi_ch-10_p-11_s-16\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以先王聖人為的不然：知夫為人主上的人或事物，不美不飾的不足以一民啊，不富不厚的不足以管下啊，不威不強的不足以禁暴勝悍啊，所以必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞他的耳；必將錭琢刻鏤，黼黻文章，以塞他的目；必將芻豢稻粱，五味芬芳，以塞他的口。然後眾人徒，備官職，漸慶賞，嚴刑罰，以戒他的心。使天下生民的屬，皆知己的所願欲的舉在是於啊，所以他的賞行；皆知己的所畏恐的舉在是於啊，所以他的罰威。賞行罰威，則賢的人或事物可得而且進啊，不肖的人或事物可得而且退啊，能不能可得而且官啊。若是則萬物得他的宜，事變得應，上得天時，下得地利，中得人和，則財貨渾渾如泉源，汸汸如河海，暴暴如丘山，不時焚燒，無所臧的。夫天下何患乎不足啊？所以儒術誠行，則天下大而且富，使而且功，撞鐘擊鼓而且和。《詩》說道：鐘鼓喤喤，管磬瑲瑲，降福穰穰，降福簡簡，威儀反反。既醉既飽，福祿來反。此的謂啊。所以墨術誠行，則天下尚儉而且彌貧，絕不是鬥而且日爭，勞苦頓萃，而且愈無功，愀然憂戚絕不是樂，而且日不和。《詩》說道：天方薦瘥，喪亂弘多，民言無嘉，憯莫懲嗟。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 11 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故先王聖人為之不然：知夫為人主上者，不美不飾之不足以一民也，不富不厚之不足以管下也，不威不強之不足以禁暴勝悍也，故必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞其耳」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故先王聖人為之不然：知夫為人主上者，不美不飾之不足以……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-12\",\"chapterId\":\"xunzi_ch-10\",\"order\":12,\"canonicalText\":\"垂事養民，拊循之，唲嘔之，冬日則為之饘粥，夏日則為之瓜麮，以偷取少頃之譽焉，是偷道也。可以少頃得姦民之譽，然而非長久之道也；事必不就，功必不立，是姦治者也。傮然要時務民，進事長功，輕非譽而恬失民，事進矣，而百姓疾之，是又偷偏者也。徙壞墮落，必反無功。故垂事養譽，不可；以遂功而忘民，亦不可。皆姦道也。\",\"sentenceIds\":[\"xunzi_ch-10_p-12_s-1\",\"xunzi_ch-10_p-12_s-2\",\"xunzi_ch-10_p-12_s-3\",\"xunzi_ch-10_p-12_s-4\",\"xunzi_ch-10_p-12_s-5\",\"xunzi_ch-10_p-12_s-6\",\"xunzi_ch-10_p-12_s-7\",\"xunzi_ch-10_p-12_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"垂事養民，拊循的，唲嘔的，冬日則為的饘粥，夏日則為的瓜麮，以偷取少頃的譽焉，是偷道啊。可以少頃得姦民的譽，然而且絕不是長久的道啊；事必不就，功必不立，是姦治的人或事物啊。傮然要時務民，進事長功，輕絕不是譽而且恬失民，事進矣，而且百姓疾的，是又偷偏的人或事物啊。徙壞墮落，必反無功。所以垂事養譽，不可；以遂功而且忘民，亦不可。皆姦道啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 12 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「垂事養民，拊循之，唲嘔之，冬日則為之饘粥，夏日則為之瓜麮，以偷取少頃之譽焉，是偷道也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「垂事養民，拊循之，唲嘔之，冬日則為之饘粥，夏日則為之……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-13\",\"chapterId\":\"xunzi_ch-10\",\"order\":13,\"canonicalText\":\"故古人為之不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富；而百姓皆愛其上，人歸之如流水，親之歡如父母，為之出死斷亡而愉者，無它故焉，忠信、調和、均辨之至也。故國君長民者，欲趨時遂功，則和調累解，速乎急疾；忠信均辨，說乎慶賞矣；必先脩正其在我者，然後徐責其在人者，威乎刑罰。三德者誠乎上，則下應之如景嚮，雖欲無明達，得乎哉！《書》曰：「乃大明服，惟民其力懋，和而有疾。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-13_s-1\",\"xunzi_ch-10_p-13_s-2\",\"xunzi_ch-10_p-13_s-3\",\"xunzi_ch-10_p-13_s-4\",\"xunzi_ch-10_p-13_s-5\",\"xunzi_ch-10_p-13_s-6\",\"xunzi_ch-10_p-13_s-7\",\"xunzi_ch-10_p-13_s-8\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以古人為的不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富；而且百姓皆愛他的上，人歸的如流水，親的歡如父母，為的出死斷亡而且愉的人或事物，無它所以焉，忠信、調和、均辨的至啊。所以國君長民的人或事物，欲趨時遂功，則和調累解，速乎急疾；忠信均辨，說乎慶賞矣；必先脩正他的在我的人或事物，然後徐責他的在人的人或事物，威乎刑罰。三品德修養的人或事物誠乎上，則下應的如景嚮，雖欲無明達，得乎哉！《書》說道：乃大明服，惟民他的力懋，和而且有疾。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 13 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故古人為之不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故古人為之不然：使民夏不宛喝，冬不凍寒，急不傷力，緩……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-14\",\"chapterId\":\"xunzi_ch-10\",\"order\":14,\"canonicalText\":\"故不教而誅，則刑繁而邪不勝；教而不誅，則姦民不懲；誅而不賞，則勤厲之民不勸；誅賞而不類，則下疑俗險而百姓不一。故先王明禮義以壹之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申重之，時其事，輕其任，以調齊之，潢然兼覆之，養長之，如保赤子。若是，故姦邪不作，盜賊不起，而化善者勸勉矣。是何邪？則其道易，其塞固，其政令一，其防表明。故曰：上一則下一矣，上二則下二矣。闢之若屮木枝葉必類本。此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-14_s-1\",\"xunzi_ch-10_p-14_s-2\",\"xunzi_ch-10_p-14_s-3\",\"xunzi_ch-10_p-14_s-4\",\"xunzi_ch-10_p-14_s-5\",\"xunzi_ch-10_p-14_s-6\",\"xunzi_ch-10_p-14_s-7\",\"xunzi_ch-10_p-14_s-8\",\"xunzi_ch-10_p-14_s-9\",\"xunzi_ch-10_p-14_s-10\",\"xunzi_ch-10_p-14_s-11\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以不教而且誅，則刑繁而且邪不勝；教而且不誅，則姦民不懲；誅而且不賞，則勤厲的民不勸；誅賞而且不類，則下疑俗險而且百姓不一。所以先王明禮正義道義道品德修養規程正義道義以壹的，致忠信以愛的，尚賢使能以次的，爵服慶賞以申重的，時他的事，輕他的任，以調齊的，潢然兼覆的，養長的，如保赤子。若是，所以姦邪不作，盜賊不起，而且化善的人或事物勸勉矣。是何邪？則他的道易，他的塞固，他的政令一，他的防表明。所以古聖先賢說道：上一則下一矣，上二則下二矣。闢的若屮木枝葉必類本。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 14 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「故不教而誅，則刑繁而邪不勝」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「故不教而誅，則刑繁而邪不勝；教而不誅，則姦民不懲；誅……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-15\",\"chapterId\":\"xunzi_ch-10\",\"order\":15,\"canonicalText\":\"不利而利之，不如利而後利之之利也。不愛而用之，不如愛而後用之之功也。利而後利之，不如利而不利者之利也。愛而後用之，不如愛而不用者之功也。利而不利也，愛而不用也者，取天下者也。利而後利之，愛而後用之者，保社稷者也。不利而利之，不愛而用之者，危國家者也。\",\"sentenceIds\":[\"xunzi_ch-10_p-15_s-1\",\"xunzi_ch-10_p-15_s-2\",\"xunzi_ch-10_p-15_s-3\",\"xunzi_ch-10_p-15_s-4\",\"xunzi_ch-10_p-15_s-5\",\"xunzi_ch-10_p-15_s-6\",\"xunzi_ch-10_p-15_s-7\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"不利而且利的，不如利而且後利的的利啊。不愛而且用的，不如愛而且後用的的功啊。利而且後利的，不如利而且不利的人或事物的利啊。愛而且後用的，不如愛而且不用的人或事物的功啊。利而且不利啊，愛而且不用啊的人或事物，取天下的人或事物啊。利而且後利的，愛而且後用的的人或事物，保社稷的人或事物啊。不利而且利的，不愛而且用的的人或事物，危國家的人或事物啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 15 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「不利而利之，不如利而後利之之利也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「不利而利之，不如利而後利之之利也。不愛而用之，不如愛……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-16\",\"chapterId\":\"xunzi_ch-10\",\"order\":16,\"canonicalText\":\"觀國之治亂臧否，至於疆易而端已見矣。其候繳支繚，其竟關之政盡察，是亂國已。入其境，其田疇穢，都邑露，是貪主已。觀其朝廷，則其貴者不賢；觀其官職，則其治者不能；觀其便嬖，則其信者不愨，是闇主已。凡主相臣下百吏之屬，其於貨財取與計數也，順孰盡察；其禮義節奏也，芒軔僈楛，是辱國已。其耕者樂田，其戰士安難，其百吏好法，其朝廷隆禮，其卿相調議，是治國已。觀其朝廷，則其貴者賢；觀其官職，則其治者能；觀其便嬖，則其信者愨，是明主已。凡主相臣下百吏之屬，其於貨財取與計數也，寬饒簡易；其於禮義節奏也，陵謹盡察，是榮國已。賢齊則其親者先貴，能齊則其故者先官，其臣下百吏，汙者皆化而脩，悍者皆化而願，躁者皆化而愨，是明主之功已。\",\"sentenceIds\":[\"xunzi_ch-10_p-16_s-1\",\"xunzi_ch-10_p-16_s-2\",\"xunzi_ch-10_p-16_s-3\",\"xunzi_ch-10_p-16_s-4\",\"xunzi_ch-10_p-16_s-5\",\"xunzi_ch-10_p-16_s-6\",\"xunzi_ch-10_p-16_s-7\",\"xunzi_ch-10_p-16_s-8\",\"xunzi_ch-10_p-16_s-9\",\"xunzi_ch-10_p-16_s-10\",\"xunzi_ch-10_p-16_s-11\",\"xunzi_ch-10_p-16_s-12\",\"xunzi_ch-10_p-16_s-13\",\"xunzi_ch-10_p-16_s-14\",\"xunzi_ch-10_p-16_s-15\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"觀國的治亂臧否，至於疆易而且端已見矣。他的候繳支繚，他的竟關的政盡察，是亂國已。入他的境，他的田疇穢，都邑露，是貪主已。觀他的朝廷，則他的貴的人或事物不賢；觀他的官職，則他的治的人或事物不能；觀他的便嬖，則他的信的人或事物不愨，是闇主已。凡主相臣下百吏的屬，他的於貨財取與計數啊，順孰盡察；他的禮正義道義道品德修養規程正義道義節奏啊，芒軔僈楛，是辱國已。他的耕的人或事物樂田，他的戰士安難，他的百吏好國家典章法度，他的朝廷隆禮正義道義道品德修養規程，他的卿相調議，是治國已。觀他的朝廷，則他的貴的人或事物賢；觀他的官職，則他的治的人或事物能；觀他的便嬖，則他的信的人或事物愨，是明主已。凡主相臣下百吏的屬，他的於貨財取與計數啊，寬饒簡易；他的於禮正義道義道品德修養規程正義道義節奏啊，陵謹盡察，是榮國已。賢齊則他的親的人或事物先貴，能齊則他的所以的人或事物先官，他的臣下百吏，汙的人或事物皆化而且脩，悍的人或事物皆化而且願，躁的人或事物皆化而且愨，是明主的功已。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 16 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「觀國之治亂臧否，至於疆易而端已見矣」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「觀國之治亂臧否，至於疆易而端已見矣。其候繳支繚，其竟……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-17\",\"chapterId\":\"xunzi_ch-10\",\"order\":17,\"canonicalText\":\"觀國之強弱貧富有徵：上不隆禮則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱。上好功則國貧，上好利則國貧，士大夫眾則國貧，工商眾則國貧，無制數度量則國貧。下貧則上貧，下富則上富。故田野縣鄙者，財之本也；垣窌倉廩者，財之末也。百姓時和，事業得敘者，貨之源也；等賦府庫者，貨之流也。故明主必謹養其和，節其流，開其源，而時斟酌焉。潢然使天下必有餘，而上不憂不足。如是，則上下俱富，交無所藏之。是知國計之極也。故禹十年水，湯七年旱，而天下無菜色者，十年之後，年穀復孰，而陳積有餘。是無它故焉，知本末源流之謂也。故田野荒而倉廩實，百姓虛而府庫滿，夫是之謂國蹶。伐其本，竭其源，而並之其末，然而主相不知惡也，則其傾覆滅亡可立而待也。以國持之，而不足以容其身，夫是之謂至貧，是愚主之極也。將以取富而喪其國，將以取利而危其身，古有萬國，今有十數焉，是無它故焉，其所以失之一也。君人者亦可以覺矣。百里之國，足以獨立矣。\",\"sentenceIds\":[\"xunzi_ch-10_p-17_s-1\",\"xunzi_ch-10_p-17_s-2\",\"xunzi_ch-10_p-17_s-3\",\"xunzi_ch-10_p-17_s-4\",\"xunzi_ch-10_p-17_s-5\",\"xunzi_ch-10_p-17_s-6\",\"xunzi_ch-10_p-17_s-7\",\"xunzi_ch-10_p-17_s-8\",\"xunzi_ch-10_p-17_s-9\",\"xunzi_ch-10_p-17_s-10\",\"xunzi_ch-10_p-17_s-11\",\"xunzi_ch-10_p-17_s-12\",\"xunzi_ch-10_p-17_s-13\",\"xunzi_ch-10_p-17_s-14\",\"xunzi_ch-10_p-17_s-15\",\"xunzi_ch-10_p-17_s-16\",\"xunzi_ch-10_p-17_s-17\",\"xunzi_ch-10_p-17_s-18\",\"xunzi_ch-10_p-17_s-19\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"觀國的強弱貧富有徵：上不隆禮正義道義道品德修養規程則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱。上好功則國貧，上好利則國貧，士大夫眾則國貧，工商眾則國貧，無制數度量則國貧。下貧則上貧，下富則上富。所以田野縣鄙的人或事物，財的本啊；垣窌倉廩的人或事物，財的末啊。百姓時和，事業得敘的人或事物，貨的源啊；等賦府庫的人或事物，貨的流啊。所以明主必謹養他的和，節他的流，開他的源，而且時斟酌焉。潢然使天下必有餘，而且上不憂不足。如是，則上下俱富，交無所藏的。是知國計的極啊。所以禹十年水，湯七年旱，而且天下無菜色的人或事物，十年的後，年穀復孰，而且陳積有餘。是無它所以焉，知本末源流的謂啊。所以田野荒而且倉廩實，百姓虛而且府庫滿，這就是儒家所稱的國蹶。伐他的本，竭他的源，而且並的他的末，然而且主相不知惡啊，則他的傾覆滅亡可立而且待啊。以國持的，而且不足以容他的身，這就是儒家所稱的至貧，是愚主的極啊。將以取富而且喪他的國，將以取利而且危他的身，古有萬國，今有十數焉，是無它所以焉，他的所以失的一啊。君人的人或事物亦可以覺矣。百里的國，足以獨立矣。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 17 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「觀國之強弱貧富有徵：上不隆禮則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「觀國之強弱貧富有徵：上不隆禮則兵弱，上不愛民則兵弱，……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-18\",\"chapterId\":\"xunzi_ch-10\",\"order\":18,\"canonicalText\":\"凡攻人者，非以為名，則案以為利也；不然則忿之也。仁人之用國，將脩志意，正身行，伉隆高，致忠信，期文理。布衣紃屨之士誠是，則雖在窮閻漏屋，而王公不能與之爭名；以國載之，則天下莫之能隱匿也。若是則為名者不攻也。將闢田野，實倉廩，便備用，上下一心，三軍同力，與之遠舉極戰則不可；境內之聚也保固；視可，午其軍，取其將，若撥麷。彼得之，不足以藥傷補敗。彼愛其爪牙，畏其仇敵，若是則為利者不攻也。將脩大小強弱之義，以持慎之，禮節將甚文，珪璧將甚碩，貨賂將甚厚，所以說之者，必將雅文辯慧之君子也。彼苟有人意焉，夫誰能忿之？若是，則忿之者不攻也。為名者否，為利者否，為忿者否，則國安於盤石，壽於旗翼。人皆亂，我獨治；人皆危，我獨安；人皆喪失之，我按起而治之。故仁人之用國，非特將持其有而已也，又將兼人。《詩》曰：「淑人君子，其儀不忒；其儀不忒，正是四國。」此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-18_s-1\",\"xunzi_ch-10_p-18_s-2\",\"xunzi_ch-10_p-18_s-3\",\"xunzi_ch-10_p-18_s-4\",\"xunzi_ch-10_p-18_s-5\",\"xunzi_ch-10_p-18_s-6\",\"xunzi_ch-10_p-18_s-7\",\"xunzi_ch-10_p-18_s-8\",\"xunzi_ch-10_p-18_s-9\",\"xunzi_ch-10_p-18_s-10\",\"xunzi_ch-10_p-18_s-11\",\"xunzi_ch-10_p-18_s-12\",\"xunzi_ch-10_p-18_s-13\",\"xunzi_ch-10_p-18_s-14\",\"xunzi_ch-10_p-18_s-15\",\"xunzi_ch-10_p-18_s-16\",\"xunzi_ch-10_p-18_s-17\",\"xunzi_ch-10_p-18_s-18\",\"xunzi_ch-10_p-18_s-19\",\"xunzi_ch-10_p-18_s-20\",\"xunzi_ch-10_p-18_s-21\",\"xunzi_ch-10_p-18_s-22\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"凡攻人的人或事物，絕不是以為名，則案以為利啊；不然則忿的啊。仁愛慈悲之德人的用國，將脩志意，正身行，伉隆高，致忠信，期文理。布衣紃屨的士誠是，則雖在窮閻漏屋，而且王公不能與的爭名；以國載的，則天下莫的能隱匿啊。若是則為名的人或事物不攻啊。將闢田野，實倉廩，便備用，上下一心，三軍同力，與的遠舉極戰則不可；境內的聚啊保固；視可，午他的軍，取他的將，若撥麷。彼得的，不足以藥傷補敗。彼愛他的爪牙，畏他的仇敵，若是則為利的人或事物不攻啊。將脩大小強弱的正義道義，以持慎的，禮正義道義道品德修養規程節將甚文，珪璧將甚碩，貨賂將甚厚，所以說的的人或事物，必將雅文辯慧的君子啊。彼苟有人意焉，夫誰能忿的？若是，則忿的的人或事物不攻啊。為名的人或事物否，為利的人或事物否，為忿的人或事物否，則國安於盤石，壽於旗翼。人皆亂，我獨治；人皆危，我獨安；人皆喪失的，我按起而且治的。所以仁愛慈悲之德人的用國，絕不是特將持他的有而且已啊，又將兼人。《詩》說道：淑人君子，他的儀不忒；他的儀不忒，正是四國。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 18 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「凡攻人者，非以為名，則案以為利也」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「凡攻人者，非以為名，則案以為利也；不然則忿之也。仁人……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"xunzi_ch-10_p-19\",\"chapterId\":\"xunzi_ch-10\",\"order\":19,\"canonicalText\":\"持國之難易：事強暴之國難，使強暴之國事我易。事之以貨寶，則貨寶單，而交不結；約信盟誓，則約定而畔無日；割國之錙銖以賂之，則割定而欲無厭。事之彌煩，其侵人愈甚，必至於資單國舉然後已。雖左堯而右舜，未有能以此道得免焉者也。譬之是猶使處女嬰寶珠，佩寶玉，負戴黃金，而遇中山之盜也，雖為之逢蒙視，詘要撓膕，君盧屋妾，由將不足以免也。故非有一人之道也，直將巧繁拜請而畏事之，則不足以持國安身。故明君不道也。必將脩禮以齊朝，正法以齊官，平政以齊民；然後節奏齊於朝，百事齊於官，眾庶齊於下。如是，則近者競親，遠方致願，上下一心，三軍同力，名聲足以暴炙之，威強足以捶笞之，拱揖指揮，而強暴之國莫不趨使，譬之是猶烏獲與焦僥搏也。故曰：事強暴之國難，使強暴之國事我易。此之謂也。\",\"sentenceIds\":[\"xunzi_ch-10_p-19_s-1\",\"xunzi_ch-10_p-19_s-2\",\"xunzi_ch-10_p-19_s-3\",\"xunzi_ch-10_p-19_s-4\",\"xunzi_ch-10_p-19_s-5\",\"xunzi_ch-10_p-19_s-6\",\"xunzi_ch-10_p-19_s-7\",\"xunzi_ch-10_p-19_s-8\",\"xunzi_ch-10_p-19_s-9\",\"xunzi_ch-10_p-19_s-10\",\"xunzi_ch-10_p-19_s-11\",\"xunzi_ch-10_p-19_s-12\",\"xunzi_ch-10_p-19_s-13\",\"xunzi_ch-10_p-19_s-14\"],\"sourceRefs\":[{\"label\":\"《荀子》—中國哲學書電子化計劃\",\"edition\":\"王先謙《荀子集解》本\",\"location\":\"https://ctext.org/xunzi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《荀子》—維基文庫\",\"edition\":\"楊倞注《荀子》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/荀子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"持國的難易：事強暴的國難，使強暴的國事我易。事的以貨寶，則貨寶單，而且交不結；約信盟誓，則約定而且畔無日；割國的錙銖以賂的，則割定而且欲無厭。事的彌煩，他的侵人愈甚，必至於資單國舉然後已。雖左堯而且右舜，未有能以此道得免焉的人或事物啊。譬的是猶使處女嬰寶珠，佩寶玉，負戴黃金，而且遇中山的盜啊，雖為的逢蒙視，詘要撓膕，君盧屋妾，由將不足以免啊。所以絕不是有一人的道啊，直將巧繁拜請而且畏事的，則不足以持國安身。所以明君不道啊。必將脩禮正義道義道品德修養規程以齊朝，正國家典章法度以齊官，平政以齊民；然後節奏齊於朝，百事齊於官，眾庶齊於下。如是，則近的人或事物競親，遠方致願，上下一心，三軍同力，名聲足以暴炙的，威強足以捶笞的，拱揖指揮，而且強暴的國莫不趨使，譬的是猶烏獲與焦僥搏啊。所以古聖先賢說道：事強暴的國難，使強暴的國事我易。此的謂啊。\",\"analysis\":\"【荀學篇旨與核心哲思】\\\\n本段選自先秦儒學集大成之作《荀子》〈富國〉（第 19 節）。文本依據唐楊倞注與清王先謙《荀子集解》之權威學術體系，深刻闡發了荀子「化性起偽」、「隆禮重法」、「明分使羣」與「天行有常」之哲學主旨。開篇「持國之難易：事強暴之國難，使強暴之國事我易」提綱挈領，立意宏遠。\\\\n\\\\n【名物義理與章法論辯】\\\\n1. 概念範疇與論證推進：全段聚焦「持國之難易：事強暴之國難，使強暴之國事我易。事之以貨……」，荀子善用嚴密之邏輯推理、對比論證與生動譬喻，層層剖析人性自私與社會秩序之建構，論證禮義法度乃聖人積思慮、習偽故所生之社會規範。\\\\n2. 語言風格與先秦散文特色：文氣雄渾博大、句式整飭駢散結合，說理透闢犀利，既重道德禮義之教化，又重功用實效與制度規章。\\\\n\\\\n【經世致用與儒學集大成】\\\\n荀子整合先秦諸子學術精華，兼取法家之法治勢能與墨家之尚賢節用，將儒家仁義思想落實為具體的禮樂刑政與王霸之道，為後世大一統王朝之制度文明與經學思想奠定了堅實根基。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"xunzi_ch-10_p-1_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":1,\"canonicalText\":\"萬物同宇而異體，無宜而有用為人，數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":2,\"canonicalText\":\"人倫並處，同求而異道，同欲而異知，生也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":3,\"canonicalText\":\"皆有可也，知愚同；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":4,\"canonicalText\":\"所可異也，知愚分。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":5,\"canonicalText\":\"埶同而知異，行私而無禍，縱欲而不窮，則民心奮而不可說也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":6,\"canonicalText\":\"如是，則知者未得治也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":7,\"canonicalText\":\"知者未得治，則功名未成也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":8,\"canonicalText\":\"功名未成，則羣眾未縣也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":9,\"canonicalText\":\"羣眾未縣，則君臣未立也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":10,\"canonicalText\":\"無君以制臣，無上以制下，天下害生縱欲。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":11,\"canonicalText\":\"欲惡同物，欲多而物寡，寡則必爭矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":12,\"canonicalText\":\"故百技所成，所以養一人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":13,\"canonicalText\":\"而能不能兼技，人不能兼官。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":14,\"canonicalText\":\"離居不相待則窮，羣居而無分則爭；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":15,\"canonicalText\":\"窮者患也，爭者禍也，救患除禍，則莫若明分使羣矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":16,\"canonicalText\":\"彊脅弱也，知懼愚也，民下違上，少陵長，不以德為政：如是，則老弱有失養之憂，而壯者有分爭之禍矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":17,\"canonicalText\":\"事業所惡也，功利所好也，職業無分：如是，則人有樹事之患，而有爭功之禍矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":18,\"canonicalText\":\"男女之合，夫婦之分，婚姻娉內，送逆無禮：如是，則人有失合之憂，而有爭色之禍矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-1_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-1\",\"order\":19,\"canonicalText\":\"故知者為之分也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":1,\"canonicalText\":\"足國之道：節用裕民，而善臧其餘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":2,\"canonicalText\":\"節用以禮，裕民以政。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":3,\"canonicalText\":\"彼裕民，故多餘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":4,\"canonicalText\":\"裕民則民富，民富則田肥以易，田肥以易則出實百倍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":5,\"canonicalText\":\"上以法取焉，而下以禮節用之，餘若丘山，不時焚燒，無所臧之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":6,\"canonicalText\":\"夫君子奚患乎無餘？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":7,\"canonicalText\":\"故知節用裕民，則必有仁聖賢良之名，而且有富厚丘山之積矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":8,\"canonicalText\":\"此無他故焉，生於節用裕民也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":9,\"canonicalText\":\"不知節用裕民則民貧，民貧則田瘠以穢，田瘠以穢則出實不半；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":10,\"canonicalText\":\"上雖好取侵奪，猶將寡獲也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":11,\"canonicalText\":\"而或以無禮節用之，則必有貪利糾譑之名，而且有空虛窮乏之實矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":12,\"canonicalText\":\"此無他故焉，不知節用裕民也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":13,\"canonicalText\":\"《康誥》曰：「弘覆乎天，若德裕乃身。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-2_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-2\",\"order\":14,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":1,\"canonicalText\":\"禮者，貴賤有等；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":2,\"canonicalText\":\"長幼有差，貧富輕重皆有稱者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":3,\"canonicalText\":\"故天子袾裷衣冕，諸侯玄裷衣冕，大夫裨冕，士皮弁服。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":4,\"canonicalText\":\"德必稱位，位必稱祿，祿必稱用，由士以上則必以禮樂節之，眾庶百姓則必以法數制之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":5,\"canonicalText\":\"量地而立國，計利而畜民，度人力而授事，使民必勝事，事必出利，利足以生民，皆使衣食百用出入相揜，必時臧餘，謂之稱數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":6,\"canonicalText\":\"故自天子通於庶人，事無大小多少，由是推之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":7,\"canonicalText\":\"故曰：「朝無幸位，民無幸生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":8,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":9,\"canonicalText\":\"輕田野之賦，平關市之徵，省商賈之數，罕興力役，無奪農時，如是則國富矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-3_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-3\",\"order\":10,\"canonicalText\":\"夫是之謂以政裕民。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":1,\"canonicalText\":\"人之生不能無羣，羣而無分則爭，爭則亂，亂則窮矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":2,\"canonicalText\":\"故無分者，人之大害也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":3,\"canonicalText\":\"有分者，天下之本利也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":4,\"canonicalText\":\"而人君者，所以管分之樞要也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":5,\"canonicalText\":\"故美之者，是美天下之本也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":6,\"canonicalText\":\"安之者，是安天下之本也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":7,\"canonicalText\":\"貴之者，是貴天下之本也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":8,\"canonicalText\":\"古者先王分割而等異之也，故使或美，或惡，或厚，或薄，或佚或樂，或劬或勞，非特以為淫泰誇麗之聲，將以明仁之文，通仁之順也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":9,\"canonicalText\":\"故為之雕琢、刻鏤、黼黻文章，使足以辨貴賤而已，不求其觀；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":10,\"canonicalText\":\"為之鐘鼓、管磬、琴瑟、竽笙，使足以辨吉凶、合歡、定和而已，不求其餘；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":11,\"canonicalText\":\"為之宮室、臺榭，使足以避燥溼、養德、辨輕重而已，不求其外。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":12,\"canonicalText\":\"《詩》曰：「雕琢其章，金玉其相，亹亹我王，綱紀四方。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-4_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-4\",\"order\":13,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":1,\"canonicalText\":\"若夫重色而衣之，重味而食之，重財物而制之，合天下而君之，非特以為淫泰也，固以為主天下，治萬變，材萬物，養萬民，兼制天下者，為莫若仁人之善也夫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":2,\"canonicalText\":\"故其知慮足以治之，其仁厚足以安之，其德音足以化之，得之則治，失之則亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":3,\"canonicalText\":\"百姓誠賴其知也，故相率而為之勞苦以務佚之，以養其知也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":4,\"canonicalText\":\"誠美其厚也，故為之出死斷亡以覆救之，以養其厚也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":5,\"canonicalText\":\"誠美其德也，故為之雕琢、刻鏤、黼黻、文章以藩飾之，以養其德也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":6,\"canonicalText\":\"故仁人在上，百姓貴之如帝，親之如父母，為之出死斷亡而愉者，無它故焉，其所是焉誠美，其所得焉誠大，其所利焉誠多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":7,\"canonicalText\":\"《詩》曰：「我任我輦，我車我牛，我行既集，蓋雲歸哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-5_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-5\",\"order\":8,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":1,\"canonicalText\":\"故曰：君子以德，小人以力；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":2,\"canonicalText\":\"力者，德之役也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":3,\"canonicalText\":\"百姓之力，待之而後功；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":4,\"canonicalText\":\"百姓之羣，待之而後和；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":5,\"canonicalText\":\"百姓之財，待之而後聚；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":6,\"canonicalText\":\"百姓之埶，待之而後安；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":7,\"canonicalText\":\"百姓之壽，待之而後長；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":8,\"canonicalText\":\"父子不得不親，兄弟不得不順，男女不得不歡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":9,\"canonicalText\":\"少者以長，老者以養。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":10,\"canonicalText\":\"故曰：「天地生之，聖人成之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-6_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-6\",\"order\":11,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":1,\"canonicalText\":\"今之世而不然：厚刀布之斂，以奪之財；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":2,\"canonicalText\":\"重田野之賦，以奪之食；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":3,\"canonicalText\":\"苛關市之徵，以難其事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":4,\"canonicalText\":\"不然而已矣：有掎絜伺詐，權謀傾覆，以相顛倒，以靡敝之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":5,\"canonicalText\":\"百姓曉然皆知其汙漫暴亂，而將大危亡也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":6,\"canonicalText\":\"是以臣或弒其君，下或殺其上，粥其城，倍其節，而不死其事者，無他故焉，人主自取之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":7,\"canonicalText\":\"《詩》曰：「無言不讎，無德不報。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-7_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-7\",\"order\":8,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-8_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-8\",\"order\":1,\"canonicalText\":\"兼足天下之道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-8_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-8\",\"order\":2,\"canonicalText\":\"守時力民，進事長功，和齊百姓，使人不偷，是將率之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-8_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-8\",\"order\":3,\"canonicalText\":\"高者不旱，下者不水，寒暑和節，而五穀以時孰，是天之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-8_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-8\",\"order\":4,\"canonicalText\":\"若夫兼而覆之，兼而愛之，兼而制之，歲雖兇敗水旱，使百姓無凍餧之患，則是聖君賢相之事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":1,\"canonicalText\":\"墨子之言昭昭然為天下憂不足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":2,\"canonicalText\":\"夫不足非天下之公患也，特墨子之私憂過計也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":3,\"canonicalText\":\"今是土之生五穀也，人善治之，則畝數盆，一歲而再獲之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":4,\"canonicalText\":\"然後瓜桃棗李一本數以盆鼓；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":5,\"canonicalText\":\"然後葷菜百疏以澤量；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":6,\"canonicalText\":\"然後六畜禽獸一而剸車；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":7,\"canonicalText\":\"黿、鼉、魚、鱉、鰍、鱣以時別，一而成羣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":8,\"canonicalText\":\"然後飛鳥、鳧、雁若煙海；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":9,\"canonicalText\":\"然後昆蟲萬物生其間，可以相食養者，不可勝數也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":10,\"canonicalText\":\"夫天地之生萬物也，固有餘，足以食人矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":11,\"canonicalText\":\"麻葛繭絲、鳥獸之羽毛齒革也，固有餘，足以衣人矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-9_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-9\",\"order\":12,\"canonicalText\":\"夫有餘不足，非天下之公患也，特墨子之私憂過計也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":1,\"canonicalText\":\"天下之公患，亂傷之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":2,\"canonicalText\":\"胡不嘗試相與求亂之者誰也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":3,\"canonicalText\":\"我以墨子之「非樂」也，則使天下亂；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":4,\"canonicalText\":\"墨子之「節用」也，則使天下貧，非將墮之也，說不免焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":5,\"canonicalText\":\"墨子大有天下，小有一國，將蹙然衣粗食惡，憂戚而非樂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":6,\"canonicalText\":\"若是則瘠，瘠則不足欲；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":7,\"canonicalText\":\"不足欲則賞不行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":8,\"canonicalText\":\"墨子大有天下，小有一國，將少人徒，省官職，上功勞苦，與百姓均事業，齊功勞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":9,\"canonicalText\":\"若是則不威；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":10,\"canonicalText\":\"不威則罰不行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":11,\"canonicalText\":\"賞不行，則賢者不可得而進也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":12,\"canonicalText\":\"罰不行，則不肖者不可得而退也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":13,\"canonicalText\":\"賢者不可得而進也，不肖者不可得而退也，則能不能不可得而官也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":14,\"canonicalText\":\"若是，則萬物失宜，事變失應，上失天時，下失地利，中失人和，天下敖然，若燒若焦，墨子雖為之衣褐帶索，嚽菽飲水，惡能足之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-10_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-10\",\"order\":15,\"canonicalText\":\"既以伐其本，竭其原，而焦天下矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":1,\"canonicalText\":\"故先王聖人為之不然：知夫為人主上者，不美不飾之不足以一民也，不富不厚之不足以管下也，不威不強之不足以禁暴勝悍也，故必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞其耳；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":2,\"canonicalText\":\"必將錭琢刻鏤，黼黻文章，以塞其目；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":3,\"canonicalText\":\"必將芻豢稻粱，五味芬芳，以塞其口。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":4,\"canonicalText\":\"然後眾人徒，備官職，漸慶賞，嚴刑罰，以戒其心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":5,\"canonicalText\":\"使天下生民之屬，皆知己之所願欲之舉在是於也，故其賞行；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":6,\"canonicalText\":\"皆知己之所畏恐之舉在是於也，故其罰威。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":7,\"canonicalText\":\"賞行罰威，則賢者可得而進也，不肖者可得而退也，能不能可得而官也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":8,\"canonicalText\":\"若是則萬物得其宜，事變得應，上得天時，下得地利，中得人和，則財貨渾渾如泉源，汸汸如河海，暴暴如丘山，不時焚燒，無所臧之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":9,\"canonicalText\":\"夫天下何患乎不足也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":10,\"canonicalText\":\"故儒術誠行，則天下大而富，使而功，撞鐘擊鼓而和。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":11,\"canonicalText\":\"《詩》曰：「鐘鼓喤喤，管磬瑲瑲，降福穰穰，降福簡簡，威儀反反。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":12,\"canonicalText\":\"既醉既飽，福祿來反。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":13,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":14,\"canonicalText\":\"故墨術誠行，則天下尚儉而彌貧，非鬥而日爭，勞苦頓萃，而愈無功，愀然憂戚非樂，而日不和。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":15,\"canonicalText\":\"《詩》曰：「天方薦瘥，喪亂弘多，民言無嘉，憯莫懲嗟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-11_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-11\",\"order\":16,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":1,\"canonicalText\":\"垂事養民，拊循之，唲嘔之，冬日則為之饘粥，夏日則為之瓜麮，以偷取少頃之譽焉，是偷道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":2,\"canonicalText\":\"可以少頃得姦民之譽，然而非長久之道也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":3,\"canonicalText\":\"事必不就，功必不立，是姦治者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":4,\"canonicalText\":\"傮然要時務民，進事長功，輕非譽而恬失民，事進矣，而百姓疾之，是又偷偏者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":5,\"canonicalText\":\"徙壞墮落，必反無功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":6,\"canonicalText\":\"故垂事養譽，不可；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":7,\"canonicalText\":\"以遂功而忘民，亦不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-12_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-12\",\"order\":8,\"canonicalText\":\"皆姦道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":1,\"canonicalText\":\"故古人為之不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":2,\"canonicalText\":\"而百姓皆愛其上，人歸之如流水，親之歡如父母，為之出死斷亡而愉者，無它故焉，忠信、調和、均辨之至也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":3,\"canonicalText\":\"故國君長民者，欲趨時遂功，則和調累解，速乎急疾；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":4,\"canonicalText\":\"忠信均辨，說乎慶賞矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":5,\"canonicalText\":\"必先脩正其在我者，然後徐責其在人者，威乎刑罰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":6,\"canonicalText\":\"三德者誠乎上，則下應之如景嚮，雖欲無明達，得乎哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":7,\"canonicalText\":\"《書》曰：「乃大明服，惟民其力懋，和而有疾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-13_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-13\",\"order\":8,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":1,\"canonicalText\":\"故不教而誅，則刑繁而邪不勝；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":2,\"canonicalText\":\"教而不誅，則姦民不懲；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":3,\"canonicalText\":\"誅而不賞，則勤厲之民不勸；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":4,\"canonicalText\":\"誅賞而不類，則下疑俗險而百姓不一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":5,\"canonicalText\":\"故先王明禮義以壹之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申重之，時其事，輕其任，以調齊之，潢然兼覆之，養長之，如保赤子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":6,\"canonicalText\":\"若是，故姦邪不作，盜賊不起，而化善者勸勉矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":7,\"canonicalText\":\"是何邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":8,\"canonicalText\":\"則其道易，其塞固，其政令一，其防表明。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":9,\"canonicalText\":\"故曰：上一則下一矣，上二則下二矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":10,\"canonicalText\":\"闢之若屮木枝葉必類本。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-14_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-14\",\"order\":11,\"canonicalText\":\"此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-15_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-15\",\"order\":1,\"canonicalText\":\"不利而利之，不如利而後利之之利也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-15_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-15\",\"order\":2,\"canonicalText\":\"不愛而用之，不如愛而後用之之功也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-15_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-15\",\"order\":3,\"canonicalText\":\"利而後利之，不如利而不利者之利也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-15_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-15\",\"order\":4,\"canonicalText\":\"愛而後用之，不如愛而不用者之功也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-15_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-15\",\"order\":5,\"canonicalText\":\"利而不利也，愛而不用也者，取天下者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-15_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-15\",\"order\":6,\"canonicalText\":\"利而後利之，愛而後用之者，保社稷者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-15_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-15\",\"order\":7,\"canonicalText\":\"不利而利之，不愛而用之者，危國家者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":1,\"canonicalText\":\"觀國之治亂臧否，至於疆易而端已見矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":2,\"canonicalText\":\"其候繳支繚，其竟關之政盡察，是亂國已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":3,\"canonicalText\":\"入其境，其田疇穢，都邑露，是貪主已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":4,\"canonicalText\":\"觀其朝廷，則其貴者不賢；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":5,\"canonicalText\":\"觀其官職，則其治者不能；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":6,\"canonicalText\":\"觀其便嬖，則其信者不愨，是闇主已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":7,\"canonicalText\":\"凡主相臣下百吏之屬，其於貨財取與計數也，順孰盡察；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":8,\"canonicalText\":\"其禮義節奏也，芒軔僈楛，是辱國已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":9,\"canonicalText\":\"其耕者樂田，其戰士安難，其百吏好法，其朝廷隆禮，其卿相調議，是治國已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":10,\"canonicalText\":\"觀其朝廷，則其貴者賢；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":11,\"canonicalText\":\"觀其官職，則其治者能；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":12,\"canonicalText\":\"觀其便嬖，則其信者愨，是明主已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":13,\"canonicalText\":\"凡主相臣下百吏之屬，其於貨財取與計數也，寬饒簡易；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":14,\"canonicalText\":\"其於禮義節奏也，陵謹盡察，是榮國已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-16_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-16\",\"order\":15,\"canonicalText\":\"賢齊則其親者先貴，能齊則其故者先官，其臣下百吏，汙者皆化而脩，悍者皆化而願，躁者皆化而愨，是明主之功已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":1,\"canonicalText\":\"觀國之強弱貧富有徵：上不隆禮則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":2,\"canonicalText\":\"上好功則國貧，上好利則國貧，士大夫眾則國貧，工商眾則國貧，無制數度量則國貧。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":3,\"canonicalText\":\"下貧則上貧，下富則上富。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":4,\"canonicalText\":\"故田野縣鄙者，財之本也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":5,\"canonicalText\":\"垣窌倉廩者，財之末也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":6,\"canonicalText\":\"百姓時和，事業得敘者，貨之源也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":7,\"canonicalText\":\"等賦府庫者，貨之流也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":8,\"canonicalText\":\"故明主必謹養其和，節其流，開其源，而時斟酌焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":9,\"canonicalText\":\"潢然使天下必有餘，而上不憂不足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":10,\"canonicalText\":\"如是，則上下俱富，交無所藏之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":11,\"canonicalText\":\"是知國計之極也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":12,\"canonicalText\":\"故禹十年水，湯七年旱，而天下無菜色者，十年之後，年穀復孰，而陳積有餘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":13,\"canonicalText\":\"是無它故焉，知本末源流之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":14,\"canonicalText\":\"故田野荒而倉廩實，百姓虛而府庫滿，夫是之謂國蹶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":15,\"canonicalText\":\"伐其本，竭其源，而並之其末，然而主相不知惡也，則其傾覆滅亡可立而待也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":16,\"canonicalText\":\"以國持之，而不足以容其身，夫是之謂至貧，是愚主之極也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":17,\"canonicalText\":\"將以取富而喪其國，將以取利而危其身，古有萬國，今有十數焉，是無它故焉，其所以失之一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":18,\"canonicalText\":\"君人者亦可以覺矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-17_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-17\",\"order\":19,\"canonicalText\":\"百里之國，足以獨立矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":1,\"canonicalText\":\"凡攻人者，非以為名，則案以為利也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":2,\"canonicalText\":\"不然則忿之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":3,\"canonicalText\":\"仁人之用國，將脩志意，正身行，伉隆高，致忠信，期文理。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":4,\"canonicalText\":\"布衣紃屨之士誠是，則雖在窮閻漏屋，而王公不能與之爭名；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":5,\"canonicalText\":\"以國載之，則天下莫之能隱匿也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":6,\"canonicalText\":\"若是則為名者不攻也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":7,\"canonicalText\":\"將闢田野，實倉廩，便備用，上下一心，三軍同力，與之遠舉極戰則不可；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":8,\"canonicalText\":\"境內之聚也保固；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":9,\"canonicalText\":\"視可，午其軍，取其將，若撥麷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":10,\"canonicalText\":\"彼得之，不足以藥傷補敗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":11,\"canonicalText\":\"彼愛其爪牙，畏其仇敵，若是則為利者不攻也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":12,\"canonicalText\":\"將脩大小強弱之義，以持慎之，禮節將甚文，珪璧將甚碩，貨賂將甚厚，所以說之者，必將雅文辯慧之君子也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":13,\"canonicalText\":\"彼苟有人意焉，夫誰能忿之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":14,\"canonicalText\":\"若是，則忿之者不攻也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-15\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":15,\"canonicalText\":\"為名者否，為利者否，為忿者否，則國安於盤石，壽於旗翼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-16\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":16,\"canonicalText\":\"人皆亂，我獨治；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-17\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":17,\"canonicalText\":\"人皆危，我獨安；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-18\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":18,\"canonicalText\":\"人皆喪失之，我按起而治之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-19\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":19,\"canonicalText\":\"故仁人之用國，非特將持其有而已也，又將兼人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-20\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":20,\"canonicalText\":\"《詩》曰：「淑人君子，其儀不忒；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-21\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":21,\"canonicalText\":\"其儀不忒，正是四國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-18_s-22\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-18\",\"order\":22,\"canonicalText\":\"」此之謂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-1\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":1,\"canonicalText\":\"持國之難易：事強暴之國難，使強暴之國事我易。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-2\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":2,\"canonicalText\":\"事之以貨寶，則貨寶單，而交不結；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-3\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":3,\"canonicalText\":\"約信盟誓，則約定而畔無日；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-4\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":4,\"canonicalText\":\"割國之錙銖以賂之，則割定而欲無厭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-5\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":5,\"canonicalText\":\"事之彌煩，其侵人愈甚，必至於資單國舉然後已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-6\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":6,\"canonicalText\":\"雖左堯而右舜，未有能以此道得免焉者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-7\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":7,\"canonicalText\":\"譬之是猶使處女嬰寶珠，佩寶玉，負戴黃金，而遇中山之盜也，雖為之逢蒙視，詘要撓膕，君盧屋妾，由將不足以免也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-8\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":8,\"canonicalText\":\"故非有一人之道也，直將巧繁拜請而畏事之，則不足以持國安身。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-9\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":9,\"canonicalText\":\"故明君不道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-10\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":10,\"canonicalText\":\"必將脩禮以齊朝，正法以齊官，平政以齊民；\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-11\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":11,\"canonicalText\":\"然後節奏齊於朝，百事齊於官，眾庶齊於下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-12\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":12,\"canonicalText\":\"如是，則近者競親，遠方致願，上下一心，三軍同力，名聲足以暴炙之，威強足以捶笞之，拱揖指揮，而強暴之國莫不趨使，譬之是猶烏獲與焦僥搏也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-13\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":13,\"canonicalText\":\"故曰：事強暴之國難，使強暴之國事我易。\",\"chunks\":[],\"tags\":[]},{\"id\":\"xunzi_ch-10_p-19_s-14\",\"workId\":\"xunzi\",\"chapterId\":\"xunzi_ch-10\",\"passageId\":\"xunzi_ch-10_p-19\",\"order\":14,\"canonicalText\":\"此之謂也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
